```bash
#!/bin/bash
set -euo pipefail

# JAIDE V25 Production Deployment Script for IONOS VPS
# This script deploys the complete JAIDE V25 system on an IONOS VPS

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
DEPLOYMENT_LOG="/var/log/jaide_v25_deployment.log"
SYSTEM_USER="jaide"
SERVICE_NAME="jaide-v25"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

log() {
    echo -e "${GREEN}[$(date +'%Y-%m-%d %H:%M:%S')] $1${NC}" | tee -a "$DEPLOYMENT_LOG"
}

warn() {
    echo -e "${YELLOW}[$(date +'%Y-%m-%d %H:%M:%S')] WARNING: $1${NC}" | tee -a "$DEPLOYMENT_LOG"
}

error() {
    echo -e "${RED}[$(date +'%Y-%m-%d %H:%M:%S')] ERROR: $1${NC}" | tee -a "$DEPLOYMENT_LOG"
    exit 1
}

check_root() {
    if [[ $EUID -ne 0 ]]; then
        error "This script must be run as root for system-level configuration"
    fi
}

detect_vps_specs() {
    log "Detecting VPS specifications..."

    CPU_CORES=$(nproc)
    MEMORY_GB=$(free -g | awk '/^Mem:/{print $2}')
    DISK_SPACE_GB=$(df -BG / | awk 'NR==2{print $2}' | sed 's/G//')

    log "VPS Specifications:"
    log "  CPU Cores: $CPU_CORES"
    log "  Memory: ${MEMORY_GB}GB"
    log "  Disk Space: ${DISK_SPACE_GB}GB"

    # Validate minimum requirements
    if [[ $CPU_CORES -lt 2 ]]; then
        error "Minimum 2 CPU cores required. Found: $CPU_CORES"
    fi

    if [[ $MEMORY_GB -lt 4 ]]; then
        error "Minimum 4GB RAM required. Found: ${MEMORY_GB}GB"
    fi

    if [[ $DISK_SPACE_GB -lt 20 ]]; then
        error "Minimum 20GB disk space required. Found: ${DISK_SPACE_GB}GB"
    fi
}

install_system_dependencies() {
