        for section, values in data.items():
            if isinstance(values, dict):
                flat_data.update(values)
            else:
                flat_data[section] = values

        return cls(**flat_data)

class NativeBridge:
    """FFI bridge to JAIDE V25 native library"""

    def __init__(self, lib_path: Path):
        self.lib_path = lib_path
        self.lib = None
        self.system_handle = None
        self._load_library()
        self._define_api()
        self._initialize_system()

    def _load_library(self):
        """Load the native JAIDE library"""
        if not self.lib_path.exists():
            raise FileNotFoundError(f"Native library not found: {self.lib_path}")

        try:
            self.lib = ctypes.CDLL(str(self.lib_path))
            logger.info("Native library loaded successfully", lib_path=str(self.lib_path))
        except OSError as e:
            logger.error("Failed to load native library", error=str(e))
            raise

    def _define_api(self):
        """Define the C API interface"""
        # System lifecycle
        self.lib.jaide_v25_system_create.restype = c_void_p
        self.lib.jaide_v25_system_create.argtypes = [c_char_p]  # config JSON

        self.lib.jaide_v25_system_destroy.argtypes = [c_void_p]
        self.lib.jaide_v25_system_destroy.restype = None

        # Training operations
        self.lib.jaide_v25_train_step.argtypes = [
            c_void_p,  # system handle
            POINTER(c_float),  # input data
            c_uint32,  # input size
            POINTER(c_float),  # target data
            c_uint32,  # target size
            POINTER(c_float)   # loss output
        ]
        self.lib.jaide_v25_train_step.restype = c_bool

        # Inference operations
        self.lib.jaide_v25_inference.argtypes = [
            c_void_p,  # system handle
            c_char_p,  # input text
            POINTER(c_char_p),  # output text
            c_uint32   # max output length
        ]
        self.lib.jaide_v25_inference.restype = c_bool

        # System information
        self.lib.jaide_v25_get_memory_usage.argtypes = [c_void_p]
        self.lib.jaide_v25_get_memory_usage.restype = c_uint32

        self.lib.jaide_v25_get_parameter_count.argtypes = [c_void_p]
        self.lib.jaide_v25_get_parameter_count.restype = c_uint32

        # Checkpointing
        self.lib.jaide_v25_save_checkpoint.argtypes = [c_void_p, c_char_p]
        self.lib.jaide_v25_save_checkpoint.restype = c_bool

        self.lib.jaide_v25_load_checkpoint.argtypes = [c_void_p, c_char_p]
        self.lib.jaide_v25_load_checkpoint.restype = c_bool

        # Cleanup
        self.lib.jaide_v25_free_string.argtypes = [c_char_p]
        self.lib.jaide_v25_free_string.restype = None

    def _initialize_system(self):
        """Initialize the JAIDE system"""
        config_json = json.dumps({
            "cpu_only": True,
            "enable_profiling": True,
            "log_level": "INFO"
        }).encode('utf-8')

        self.system_handle = self.lib.jaide_v25_system_create(config_json)
        if not self.system_handle:
            raise RuntimeError("Failed to initialize JAIDE V25 system")

        logger.info("JAIDE V25 system initialized successfully")

    def train_step(self, input_data: np.ndarray, target_data: np.ndarray) -> float:
        """Execute a single training step"""
        input_ptr = input_data.ctypes.data_as(POINTER(c_float))
        target_ptr = target_data.ctypes.data_as(POINTER(c_float))
        loss = c_float()

        success = self.lib.jaide_v25_train_step(
            self.system_handle,
            input_ptr,
            c_uint32(input_data.size),
            target_ptr,
            c_uint32(target_data.size),
            byref(loss)
        )

        if not success:
            raise RuntimeError("Training step failed")

        return loss.value

    def inference(self, text: str, max_length: int = 1000) -> str:
        """Perform inference on input text"""
        text_bytes = text.encode('utf-8')
        output_ptr = c_char_p()

        success = self.lib.jaide_v25_inference(
            self.system_handle,
            text_bytes,
            byref(output_ptr),
            c_uint32(max_length)
        )

        if not success:
            raise RuntimeError("Inference failed")

        try:
            result = ctypes.cast(output_ptr, c_char_p).value.decode('utf-8')
            return result
        finally:
            if output_ptr:
                self.lib.jaide_v25_free_string(output_ptr)

    def get_memory_usage(self) -> int:
        """Get current memory usage in bytes"""
        return self.lib.jaide_v25_get_memory_usage(self.system_handle)

    def get_parameter_count(self) -> int:
        """Get total number of model parameters"""
        return self.lib.jaide_v25_get_parameter_count(self.system_handle)

    def save_checkpoint(self, path: str) -> bool:
        """Save model checkpoint"""
        path_bytes = path.encode('utf-8')
        return self.lib.jaide_v25_save_checkpoint(self.system_handle, path_bytes)

    def load_checkpoint(self, path: str) -> bool:
        """Load model checkpoint"""
        path_bytes = path.encode('utf-8')
        return self.lib.jaide_v25_load_checkpoint(self.system_handle, path_bytes)

    def destroy(self):
        """Clean up resources"""
        if self.system_handle:
            self.lib.jaide_v25_system_destroy(self.system_handle)
            self.system_handle = None
            logger.info("JAIDE V25 system destroyed")

