                time.sleep(10)  # Longer sleep on error

class DataLoader:
    """Asynchronous data loading for training"""

    def __init__(self, config: SystemConfiguration):
        self.config = config
        self.data_queue = queue.Queue(maxsize=config.batch_size * 10)
        self.loader_thread = None
        self.running = False
