        self.running = False
        if self.loader_thread and self.loader_thread.is_alive():
            self.loader_thread.join(timeout=5)
        logger.info("Data loader stopped")

    def get_batch(self, timeout: float = 10.0) -> Optional[tuple]:
        """Get a batch of training data"""
        try:
            return self.data_queue.get(timeout=timeout)
        except queue.Empty:
            return None

    def _load_data_loop(self):
        """Data loading loop"""
        while self.running:
            try:
                # Simulate data loading - in production, this would load real training data
                batch_size = self.config.batch_size
                d_model = self.config.d_model
                seq_len = 512  # Sequence length

