                target_data = np.random.randn(batch_size, seq_len, d_model).astype(np.float32)

                if not self.data_queue.full():
                    self.data_queue.put((input_data, target_data))

                time.sleep(0.1)  # Prevent busy waiting

            except Exception as e:
