class TrainingManager:
    """Manages training process"""

    def __init__(self, config: SystemConfiguration, bridge: NativeBridge):
        self.config = config
        self.bridge = bridge
        self.training_active = False
        self.current_epoch = 0
        self.current_step = 0
        self.best_loss = float('inf')
        self.data_loader = DataLoader(config)
        self.executor = ThreadPoolExecutor(max_workers=2)
        self._training_future = None

    async def start_training(self) -> bool:
        """Start training process"""
        if self.training_active:
            logger.warning("Training already active")
            return False

        try:
            self.training_active = True
            self.data_loader.start()

            # Submit training to thread pool
            loop = asyncio.get_event_loop()
            self._training_future = loop.run_in_executor(
                self.executor, self._training_loop
            )

            logger.info("Training started", 
                       epoch=self.current_epoch, 
                       step=self.current_step)
            return True

        except Exception as e:
            logger.error("Failed to start training", error=str(e))
            self.training_active = False
            return False

    async def stop_training(self) -> bool:
        """Stop training process"""
        if not self.training_active:
            return True

        try:
            self.training_active = False
            self.data_loader.stop()

            if self._training_future:
                self._training_future.cancel()
                try:
                    await self._training_future
                except asyncio.CancelledError:
                    pass

            logger.info("Training stopped")
            return True

        except Exception as e:
            logger.error("Error stopping training", error=str(e))
            return False

    def _training_loop(self):
        """Main training loop"""
        logger.info("Training loop started")

        try:
            while self.training_active and self.current_epoch < self.config.max_epochs:
                batch_data = self.data_loader.get_batch(timeout=5.0)
                if batch_data is None:
                    continue

                input_data, target_data = batch_data

                # Flatten data for training step
                input_flat = input_data.reshape(-1)
                target_flat = target_data.reshape(-1)

                # Execute training step
                start_time = time.time()
                loss = self.bridge.train_step(input_flat, target_flat)
                step_time = time.time() - start_time

                # Update metrics
                TRAINING_STEPS.inc()
                TRAINING_LOSS.set(loss)

                self.current_step += 1

                # Logging
                if self.current_step % 10 == 0:
                    logger.info("Training step completed",
                               step=self.current_step,
                               epoch=self.current_epoch,
                               loss=loss,
                               step_time=step_time)

                # Checkpointing
                if self.current_step % self.config.checkpoint_frequency == 0:
                    self._save_checkpoint()

                # Check for improvement
                if loss < self.best_loss:
                    self.best_loss = loss
                    self._save_best_model()

                # Epoch management
                if self.current_step % 1000 == 0:  # Arbitrary steps per epoch
                    self.current_epoch += 1
                    logger.info("Epoch completed", 
                               epoch=self.current_epoch,
                               best_loss=self.best_loss)

        except Exception as e:
            logger.error("Training loop error", error=str(e), traceback=traceback.format_exc())
        finally:
            logger.info("Training loop ended")

    def _save_checkpoint(self):
        """Save training checkpoint"""
        try:
            checkpoint_path = Path(self.config.checkpoint_directory) / f"checkpoint_step_{self.current_step}.bin"
            checkpoint_path.parent.mkdir(parents=True, exist_ok=True)

            success = self.bridge.save_checkpoint(str(checkpoint_path))
            if success:
                logger.info("Checkpoint saved", path=str(checkpoint_path))
            else:
                logger.error("Failed to save checkpoint", path=str(checkpoint_path))

        except Exception as e:
            logger.error("Checkpoint save error", error=str(e))

    def _save_best_model(self):
        """Save best model"""
        try:
            best_path = Path(self.config.checkpoint_directory) / "best_model.bin"
            best_path.parent.mkdir(parents=True, exist_ok=True)

            success = self.bridge.save_checkpoint(str(best_path))
            if success:
                logger.info("Best model saved", loss=self.best_loss, path=str(best_path))

        except Exception as e:
            logger.error("Best model save error", error=str(e))

    def get_training_status(self) -> Dict[str, Any]:
        """Get current training status"""
        return {
            "active": self.training_active,
            "epoch": self.current_epoch,
            "step": self.current_step,
            "best_loss": self.best_loss,
            "memory_usage": self.bridge.get_memory_usage(),
            "parameter_count": self.bridge.get_parameter_count()
        }

