# Main Application Class
class JAIDEOrchestrator:
    """Main orchestrator for JAIDE V25 system"""

    def __init__(self, config_path: Path):
        self.config = SystemConfiguration.from_json(config_path)
        self.bridge = None
        self.monitor = None
        self.training_manager = None
        self.app = None
        self.start_time = time.time()

        # Setup logging
        log_level = getattr(logging, self.config.log_level.upper())
        logging.basicConfig(level=log_level)

        # Setup directories
        for directory in [self.config.data_directory, 
                         self.config.checkpoint_directory, 
                         self.config.log_directory]:
            Path(directory).mkdir(parents=True, exist_ok=True)

    async def initialize(self):
        """Initialize all components"""
        try:
            # Initialize native bridge
            lib_path = Path("./build/zig-out/lib/libjaide_v25.so")
            self.bridge = NativeBridge(lib_path)

            # Initialize monitoring
            self.monitor = SystemMonitor(self.config)
            self.monitor.start()

            # Initialize training manager
            self.training_manager = TrainingManager(self.config, self.bridge)

            # Update metrics
            MODEL_PARAMETERS.set(self.bridge.get_parameter_count())

            logger.info("JAIDE V25 orchestrator initialized successfully",
                       config=asdict(self.config))

        except Exception as e:
            logger.error("Initialization failed", error=str(e))
            raise

    async def shutdown(self):
        """Shutdown all components"""
        try:
            if self.training_manager:
                await self.training_manager.stop_training()

            if self.monitor:
                self.monitor.stop()

            if self.bridge:
                self.bridge.destroy()

            logger.info("JAIDE V25 orchestrator shutdown completed")

        except Exception as e:
            logger.error("Shutdown error", error=str(e))

    def create_app(self) -> FastAPI:
        """Create FastAPI application"""

        @asynccontextmanager
        async def lifespan(app: FastAPI):
            # Startup
            await self.initialize()
            yield
            # Shutdown
            await self.shutdown()

        app = FastAPI(
            title="JAIDE V25 API",
            description="Production API for JAIDE V25 AI Training System",
            version=self.config.version,
            lifespan=lifespan
        )

        # Add CORS middleware
        app.add_middleware(
            CORSMiddleware,
            allow_origins=["*"],
            allow_credentials=True,
            allow_methods=["*"],
            allow_headers=["*"],
        )

        # API endpoints
        @app.get("/health")
        async def health_check():
            """Health check endpoint"""
            return {
                "status": "healthy",
                "uptime": time.time() - self.start_time,
                "version": self.config.version
            }

        @app.post("/inference", response_model=InferenceResponse)
        async def inference(request: InferenceRequest):
            """Perform inference"""
            ACTIVE_CONNECTIONS.inc()
            try:
                start_time = time.time()
                INFERENCE_REQUESTS.inc()

                with INFERENCE_DURATION.time():
                    result = self.bridge.inference(request.text, request.max_length)

                processing_time = time.time() - start_time

                return InferenceResponse(
                    text=result,
                    processing_time=processing_time
                )

            except Exception as e:
                logger.error("Inference error", error=str(e))
                raise HTTPException(status_code=500, detail=str(e))
            finally:
                ACTIVE_CONNECTIONS.dec()

        @app.post("/training/start")
        async def start_training():
            """Start training"""
            success = await self.training_manager.start_training()
            if success:
                return {"status": "training_started"}
            else:
                raise HTTPException(status_code=400, detail="Failed to start training")

        @app.post("/training/stop")
        async def stop_training():
            """Stop training"""
            success = await self.training_manager.stop_training()
            if success:
                return {"status": "training_stopped"}
            else:
                raise HTTPException(status_code=400, detail="Failed to stop training")

        @app.get("/training/status", response_model=TrainingStatus)
        async def get_training_status():
            """Get training status"""
            status = self.training_manager.get_training_status()
            return TrainingStatus(**status)

        @app.get("/system/stats", response_model=SystemStats)
        async def get_system_stats():
            """Get system statistics"""
            cpu_usage = psutil.cpu_percent()
            memory = psutil.virtual_memory()
            disk = psutil.disk_usage('/')
            training_status = self.training_manager.get_training_status()

            return SystemStats(
                cpu_usage=cpu_usage,
                memory_usage=memory.percent,
                disk_usage=disk.percent,
                uptime=time.time() - self.start_time,
                training_status=TrainingStatus(**training_status)
            )

        @app.get("/metrics")
        async def get_metrics():
            """Prometheus metrics endpoint"""
            return generate_latest()

        @app.post("/checkpoint/save")
        async def save_checkpoint(name: str = "manual_checkpoint"):
            """Save manual checkpoint"""
            checkpoint_path = Path(self.config.checkpoint_directory) / f"{name}.bin"
            success = self.bridge.save_checkpoint(str(checkpoint_path))

            if success:
                return {"status": "checkpoint_saved", "path": str(checkpoint_path)}
            else:
                raise HTTPException(status_code=500, detail="Failed to save checkpoint")

        @app.post("/checkpoint/load")
        async def load_checkpoint(name: str):
            """Load checkpoint"""
            checkpoint_path = Path(self.config.checkpoint_directory) / f"{name}.bin"

            if not checkpoint_path.exists():
                raise HTTPException(status_code=404, detail="Checkpoint not found")

            success = self.bridge.load_checkpoint(str(checkpoint_path))

            if success:
                return {"status": "checkpoint_loaded", "path": str(checkpoint_path)}
            else:
                raise HTTPException(status_code=500, detail="Failed to load checkpoint")

        self.app = app
        return app

def signal_handler(signum, frame):
    """Handle shutdown signals"""
    logger.info("Received signal", signal=signum)
    sys.exit(0)

def main():
    """Main entry point"""
    # Setup signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Load configuration
    config_path = Path("config/production.json")
    if not config_path.exists():
        logger.error("Configuration file not found", path=str(config_path))
        sys.exit(1)

    # Create orchestrator
    orchestrator = JAIDEOrchestrator(config_path)
    app = orchestrator.create_app()

    # Run server
    uvicorn.run(
        app,
        host="0.0.0.0",
        port=8080,
        workers=1,  # Single worker for state consistency
        access_log=True,
        log_level="info"
    )

if __name__ == "__main__":
    main()
